<?php if(in_array($page,['cart','checkout'],true)){require __DIR__.'/shop-checkout.php';return;} $uid=(int)$currentUser['id']; ?>
<section class="container section shop-page">
<?php if($page==='wishlist'):?><p class="eyebrow">YOUR PERSONAL EDIT</p><h1>Saved for later.</h1><?php $products=all('SELECT p.*,c.department FROM wishlist w JOIN products p ON p.id=w.product_id JOIN categories c ON c.id=p.category_id WHERE w.user_id=? AND p.active=1',[$uid]);if(!$products):?><div class="empty-state"><h2>Your wishlist is waiting.</h2><p>Save pieces you love with the heart button.</p><a class="btn" href="<?=e(url('catalog'))?>">Explore the collection</a></div><?php else:?><div class="product-grid"><?php foreach($products as $p)product_card($p);?></div><?php endif;?>
<?php elseif($page==='orders'):?><p class="eyebrow">YOUR FORME</p><h1>Your orders.</h1><?php $orders=all('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[$uid]);if(!$orders):?><div class="empty-state"><p>No orders yet.</p><a class="btn" href="<?=e(url('catalog'))?>">Explore the collection</a></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Placed</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['reference'])?></td><td><?=e($o['created_at'])?></td><td><?=money($o['total'])?></td><td><span class="badge"><?=e($o['status'])?></span></td><td><a href="<?=e(url('order',['id'=>$o['id']]))?>">View order →</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<?php elseif($page==='order'):
$o=one('SELECT * FROM orders WHERE id=? AND user_id=?',[(int)($_GET['id']??0),$uid]);if(!$o){http_response_code(404);echo '<h1>Order not found.</h1>';return;}
?><p class="eyebrow">THANK YOU FOR CHOOSING FORME</p><h1>Your everyday is on its way.</h1><div class="order-heading"><strong><?=e($o['reference'])?></strong><span class="badge"><?=e($o['status'])?></span><span><?=e($o['created_at'])?></span></div><div class="checkout-layout"><div><?php foreach(all('SELECT * FROM order_items WHERE order_id=?',[$o['id']]) as $r):?><article class="cart-item"><img src="<?=e(safe_image($r['image']))?>" alt="<?=e($r['name'])?>"><div><h3><?=e($r['name'])?></h3><p><?=e($r['color'].' / '.$r['size'])?></p><p>Quantity: <?=$r['quantity']?></p></div><strong><?=money((float)$r['unit_price']*$r['quantity'])?></strong></article><?php endforeach;?></div><aside class="order-summary"><h2>Order details</h2><p><?=e($o['recipient'])?><br><?=e($o['phone'])?><br><?=e($o['address'])?></p><p class="summary-line"><span>Subtotal</span><span><?=money($o['subtotal'])?></span></p><p class="summary-line"><span>Discount <?=e($o['promo_code_used']??'')?></span><span>−<?=money($o['discount_amount'])?></span></p><p class="summary-line"><span>Delivery</span><span><?=money($o['shipping'])?></span></p><p class="summary-line summary-total"><span>Total</span><strong><?=money($o['total'])?></strong></p><?php $payment=one('SELECT * FROM payments WHERE order_id=?',[$o['id']]);?><p class="notice info">Payment: <?=e($payment['payment_status']??$o['payment_status'])?>. No money was collected.<?php if($payment):?><br><?=e($payment['payment_reference'])?><?php endif;?></p><?php if(in_array($o['status'],['Confirmed','Processing'],true)):?><form method="post" data-confirm="Cancel this order? Its stock will be restored."><?=token()?><input type="hidden" name="action" value="cancel_order"><input type="hidden" name="id" value="<?=$o['id']?>"><button class="btn btn-outline full">Cancel order</button></form><?php endif;?><a class="text-link" href="<?=e(url('orders'))?>">All orders →</a></aside></div>
<?php endif;?>
</section>
